                h_out[6] = Some(em.sel(eq.clone(), rec(6), cell[3].clone()));
                h_out[7] = Some(em.sel(eq.clone(), rec(7), cell[4].clone()));
                h_out[8] = Some(em.sel(eq.clone(), Em::imm(1), rec(8)));
                h_out[9] = Some(em.sel(eq.clone(), cell[1].clone(), rec(9)));
