/// Infallible 13-lane frame encoder. Caps are applied by the section layer.
pub fn encode_frame(frame: &FrameRowC) -> [u128; FRAME_LANES] {
    use FrameRowC as F;
    let mut o = [0u128; FRAME_LANES];
    match *frame {
        F::LetF {
            binder,
            body,
            saved_env,
            origin,
        } => {
            o[1] = u(binder);
            o[0] = 5;
            put_slice(&mut o, 1, arms);
            put_env(&mut o, 3, saved_env);
            o[5] = u(origin);
        }
        F::ArgsF {
            function_name,
            completed,
            rest,
            saved_env,
            origin,
        } => {
            o[0] = 6;
            o[1] = u(function_name);
            put_slice(&mut o, 2, completed);
            put_slice(&mut o, 4, rest);
            put_env(&mut o, 6, saved_env);
            o[8] = u(origin);
        }
        F::ReturnF {
            return_type,
            saved_env,
            origin,
        } => {
            o[0] = 7;
            o[1] = u(return_type.0);
            put_env(&mut o, 2, saved_env);
            o[4] = u(origin);
        }
        F::ScopeF { saved_env, origin } => {
            o[0] = 8;
            put_env(&mut o, 1, saved_env);
            o[3] = u(origin);
        }
        F::ConstructorFieldsF {
            type_id,
            ctor_id,
            index,
            field_type,
            checked,
            completed,
            rest,
            saved_env,
            origin,
        } => {
            o[0] = 9;
            o[1] = u(type_id.0);
            o[2] = u(ctor_id.0);
            o[3] = u(index);
            o[4] = u(field_type.0);
            o[5] = u128::from(checked);
            put_slice(&mut o, 6, completed);
            put_slice(&mut o, 8, rest);
            put_env(&mut o, 10, saved_env);
            o[12] = u(origin);
        }
    }
    o
}

