/// Infallible 17-lane control encoder.
pub fn encode_control(control: &ControlC) -> [u128; CONTROL_LANES] {
    use ControlC as K;
    let mut o = [0u128; CONTROL_LANES];
    match *control {
        K::Eval { expr } => o[1] = u(expr),
        K::Return { value } => {
            o[0] = 1;
            put_ref(&mut o, 1, value);
        }
        K::ScheduleNext { frame, next, env } => {
            o[0] = 2;
            o[1..1 + FRAME_LANES].copy_from_slice(&encode_frame(&frame));
            o[14] = u(next);
            put_env(&mut o, 15, env);
        }
        K::Invoke {
            function_name,
            args,
        } => {
            o[0] = 3;
            o[1] = u(function_name);
            put_slice(&mut o, 2, args);
        }
        K::Enter { function, args } => {
            o[0] = 4;
            if let Some(function) = function {
                o[1] = 1;
                o[2] = u(function);
            }
            put_slice(&mut o, 3, args);
        }
        K::Bound {
            binding,
            return_type,
            body,
        } => {
            o[0] = 5;
            if let BoundBinding::Ok { env } = binding {
                o[1] = 1;
                put_env(&mut o, 2, env);
            }
            o[4] = u(return_type.0);
            o[5] = u(body);
        }
        K::Cases {
            value,
            arms,
            saved_env,
        } => {
            o[0] = 6;
            put_ref(&mut o, 1, value);
            put_slice(&mut o, 3, arms);
            put_env(&mut o, 5, saved_env);
        }
        K::CaseResult {
            matching,
            value,
            body,
            rest,
            saved_env,
        } => {
            o[0] = 7;
            if let CaseMatching::Matched { env } = matching {
                o[1] = 1;
                put_env(&mut o, 2, env);
            }
            put_ref(&mut o, 4, value);
            o[6] = u(body);
            put_slice(&mut o, 7, rest);
            put_env(&mut o, 9, saved_env);
        }
        K::PrimResult { result } => {
            o[0] = 8;
            match result {
                PrimOutcome::Value { value } => put_ref(&mut o, 2, value),
                PrimOutcome::Error { code } => {
                    o[1] = 1;
                    o[2] = u128::from(code);
                }
            }
        }
        K::Error { code } => {
            o[0] = 9;
            o[1] = u128::from(code);
        }
        K::Materialize {
            type_id,
            ctor_id,
            fields,
        } => {
            o[0] = 10;
            o[1] = u(type_id.0);
            o[2] = u(ctor_id.0);
            put_slice(&mut o, 3, fields);
        }
        K::Await { site, expr } => {
            o[0] = 11;
            o[1] = u128::from(site);
            o[2] = u(expr);
        }
    }
    o
}

