/// Root registers of the section. Counters are carried exactly.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct C6Root {
    pub control: ControlC,
    pub control_origin: usize,
    pub env_root: EnvRootC,
    pub stack_limit: usize,
    pub outcome: OutcomeC,
    pub initial_fuel: u128,
    pub remaining_work: u128,
    pub consumed_work: u128,
    pub helper_work: u128,
    pub helper_visits: u128,
    pub reference_cursor: u128,
    pub alloc: AllocCounters,
    pub active: ActiveLengths,
    pub seg_active: ActiveLengths,
    pub seg_alloc: AllocCounters,
    pub seg_consumed_work: u128,
}

impl C6Root {
    /// Projection of the owned image registers; no field is invented.
    pub fn from_image(image: &ImageSnapshot) -> Self {
        Self {
            control: image.control,
            control_origin: image.control_origin,
            env_root: image.env_root,
            stack_limit: image.stack_limit,
            outcome: image.outcome,
            initial_fuel: image.initial_fuel,
            remaining_work: image.remaining_work,
            consumed_work: image.consumed_work,
            helper_work: image.helper_work,
            helper_visits: image.helper_visits,
            reference_cursor: image.reference_cursor,
            alloc: image.alloc,
            active: image.active,
            seg_active: image.seg_base.active(),
            seg_alloc: image.seg_base.alloc(),
            seg_consumed_work: image.seg_base.consumed_work(),
        }
    }
}

fn root_caps(root: &C6Root, c: &C6PhysCaps) -> C6Result<()> {
    control_caps(&root.control, c)?;
    cap_index(
        "root.control_origin",
        root.control_origin,
        c.max_expressions,
    )?;
    cap_env("root.env_root", root.env_root, c)?;
    cap_count("root.stack_limit", root.stack_limit, c.max_frames)?;
    if let OutcomeC::Halted { value } = root.outcome {
        cap_ref("root.outcome", value, c)?;
    }
    for (section, needed, limit) in [
        (
            "root.alloc.data_nodes",
            root.alloc.data_nodes,
            c.max_data_nodes,
        ),
        (
            "root.alloc.environment_cells",
            root.alloc.environment_cells,
            c.max_env_cells,
        ),
        ("root.active.data", root.active.data, c.max_data_nodes),
        ("root.active.env", root.active.env, c.max_env_cells),
        (
            "root.active.value_slots",
            root.active.value_slots,
            c.max_value_slots,
        ),
        (
            "root.seg_active.data",
            root.seg_active.data,
            c.max_data_nodes,
        ),
        ("root.seg_active.env", root.seg_active.env, c.max_env_cells),
        (
            "root.seg_active.value_slots",
            root.seg_active.value_slots,
            c.max_value_slots,
        ),
        (
            "root.seg_alloc.data_nodes",
            root.seg_alloc.data_nodes,
            c.max_data_nodes,
        ),
        (
            "root.seg_alloc.environment_cells",
            root.seg_alloc.environment_cells,
            c.max_env_cells,
        ),
    ] {
        cap_count(section, needed, limit)?;
    }
    Ok(())
}

fn section_len(frame_count: usize) -> C6Result<usize> {
    frame_count
        .checked_mul(FRAME_LANES)
        .and_then(|n| n.checked_add(IMAGE_SECTION_HEADER_LANES))
        .ok_or(C6PhysError::UsizeOverflow {
            section: "image_section",
            value: u(frame_count),
        })
}
fn put_alloc(out: &mut [u128], at: usize, a: AllocCounters) {
    out[at] = u(a.data_nodes);
    out[at + 1] = u(a.data_fields);
    out[at + 2] = u(a.environment_cells);
}
fn put_active(out: &mut [u128], at: usize, a: ActiveLengths) {
    out[at] = u(a.data);
    out[at + 1] = u(a.data_fields);
    out[at + 2] = u(a.env);
    out[at + 3] = u(a.value_slots);
}
fn get_alloc(s: &'static str, l: &[u128], at: usize) -> C6Result<AllocCounters> {
    Ok(AllocCounters {
        data_nodes: rd(s, l[at])?,
        data_fields: rd(s, l[at + 1])?,
        environment_cells: rd(s, l[at + 2])?,
    })
}
fn get_active(s: &'static str, l: &[u128], at: usize) -> C6Result<ActiveLengths> {
    Ok(ActiveLengths {
        data: rd(s, l[at])?,
        data_fields: rd(s, l[at + 1])?,
        env: rd(s, l[at + 2])?,
        value_slots: rd(s, l[at + 3])?,
    })
}
fn put_outcome(out: &mut [u128], at: usize, outcome: OutcomeC) {
    match outcome {
        OutcomeC::Running => {}
        OutcomeC::Halted { value } => {
            out[at] = 1;
            put_ref(out, at + 1, value);
        }
        OutcomeC::Rejected { code } => {
            out[at] = 2;
            out[at + 1] = u128::from(code);
        }
        OutcomeC::Exhausted { reason } => {
            out[at] = 3;
            out[at + 1] = exhaust_tag(reason);
        }
        OutcomeC::Waiting { site } => {
            out[at] = 4;
            out[at + 1] = u128::from(site);
        }
    }
}
fn get_outcome(s: &'static str, l: &[u128], at: usize) -> C6Result<OutcomeC> {
    match l[at] {
        0 => {
            zero(s, l, at + 1, at + 3)?;
            Ok(OutcomeC::Running)
        }
        1 => Ok(OutcomeC::Halted {
            value: get_ref(s, l, at + 1)?,
        }),
        2 => {
            let code = rd_u8(s, l[at + 1])?;
            zero(s, l, at + 2, at + 3)?;
            Ok(OutcomeC::Rejected { code })
        }
        3 => {
            let reason = exhaust_from(s, l[at + 1])?;
            zero(s, l, at + 2, at + 3)?;
            Ok(OutcomeC::Exhausted { reason })
        }
        4 => {
            let site = rd_u16(s, l[at + 1])?;
            zero(s, l, at + 2, at + 3)?;
            Ok(OutcomeC::Waiting { site })
        }
        tag => Err(C6PhysError::BadTag { section: s, tag }),
    }
}

/// Root+frames encoder. Caps are checked (root, frame count, frames) before
/// any allocation; the output is the unique canonical section.
pub fn encode_root_and_frames(
    root: &C6Root,
    frames: &[FrameRowC],
    caps: &C6PhysCaps,
) -> C6Result<Vec<u128>> {
    root_caps(root, caps)?;
    cap_count("frames", frames.len(), caps.max_frames)?;
    for frame in frames {
        frame_caps(frame, caps)?;
    }
    let mut out = vec![0u128; section_len(frames.len())?];
    out[L_MAGIC] = C6_PHYS_MAGIC;
    out[L_VERSION] = C6_PHYS_VERSION;
    out[L_CONTROL..L_CONTROL + CONTROL_LANES].copy_from_slice(&encode_control(&root.control));
    out[L_CONTROL_ORIGIN] = u(root.control_origin);
    put_env(&mut out, L_ENV_ROOT, root.env_root);
    out[L_STACK_LIMIT] = u(root.stack_limit);
    put_outcome(&mut out, L_OUTCOME, root.outcome);
    out[L_INITIAL_FUEL] = root.initial_fuel;
    out[L_REMAINING_WORK] = root.remaining_work;
    out[L_CONSUMED_WORK] = root.consumed_work;
    out[L_HELPER_WORK] = root.helper_work;
    out[L_HELPER_VISITS] = root.helper_visits;
    out[L_REFERENCE_CURSOR] = root.reference_cursor;
    put_alloc(&mut out, L_ALLOC, root.alloc);
    put_active(&mut out, L_ACTIVE, root.active);
    put_active(&mut out, L_SEG_ACTIVE, root.seg_active);
    put_alloc(&mut out, L_SEG_ALLOC, root.seg_alloc);
    out[L_SEG_CONSUMED_WORK] = root.seg_consumed_work;
    out[L_FRAME_COUNT] = u(frames.len());
    for (chunk, frame) in out[IMAGE_SECTION_HEADER_LANES..]
        .chunks_exact_mut(FRAME_LANES)
        .zip(frames)
    {
        chunk.copy_from_slice(&encode_frame(frame));
    }
    Ok(out)
}

pub fn encode_image_section(image: &ImageSnapshot, caps: &C6PhysCaps) -> C6Result<Vec<u128>> {
    encode_root_and_frames(&C6Root::from_image(image), &image.frames, caps)
}

/// Decoder; see the module documentation for the exact first-error order.
pub fn decode_image_section(
    lanes: &[u128],
    sel: &Selected,
) -> Result<StepResult, HostViolation> {
    if v.rule() != sel.rule {
        return Err(invalid_plan("ValidatedPlan rule != Selected rule"));
    }
    let adm = img.admission.clone();
    let pre = snap(&PreImage::bind(&adm, img)?)?; // before any write; on the owner_step path site(pre) already succeeded in PS select
    let ordinal = pre
        .consumed
        .checked_sub(1)
        .ok_or_else(|| arith("event ordinal consumedWork - 1"))?;
    let next_alloc_data_nodes = if v.delta.alloc_data_nodes > 0 {
        img.alloc
            .data_nodes
            .checked_add(v.delta.alloc_data_nodes as usize)
            .ok_or_else(|| arith("P7 alloc.dataNodes + 1"))?
    } else {
        img.alloc.data_nodes
    };
    let next_alloc_data_fields = if v.delta.alloc_data_fields > 0 {
        img.alloc
            .data_fields
            .checked_add(v.delta.alloc_data_fields as usize)
            .ok_or_else(|| arith("P7 alloc.dataFields + fieldLen"))?
    } else {
        img.alloc.data_fields
    };
    let next_alloc_environment_cells = if v.writes.alloc_env.is_some() {
        img.alloc
            .environment_cells
            .checked_add(1)
            .ok_or_else(|| arith("P7 alloc.environmentCells + 1"))?
    } else {
        img.alloc.environment_cells
    };
    let next_helper_visits = img
        .helper_visits
        .checked_add(u128::from(sel.helper_visits))
        .ok_or_else(|| arith("P7 helperVisits + visits"))?;
    let next_reference_cursor = if sel.event_kind == EventKind::LegacyComplete {
        img.reference_cursor
            .checked_add(1)
            .ok_or_else(|| arith("P7 referenceCursor + 1"))?
    } else {
        img.reference_cursor
    };
    let w = v.writes;
    let data_start = img.active.data;
    let fields_start = img.active.data_fields;
    let env_start = img.active.env;
    // Register field writes first (control, origin, env root, result, helper).
    if let Write::Set(c) = w.control {
        img.control = c;
    }
    if let Write::Set(c) = w.control_origin {
        img.control_origin = c;
    }
    if let Write::Set(e) = w.env_root {
        img.env_root = e;
    }
    if let Write::Set(r) = w.result {
        img.result = r;
    }
    if let Write::Set(h) = w.helper {
        img.helper = h;
    }
            exhausted,
        ),
    }
}
/// Full AB/P0/P1/P2/PS/P3/P4/P6/P7 driver. `families` is the passed FamilyPlans dependency.
pub fn owner_step(
    a: &Admitted,
    img: &mut MachineImage,
    families: &dyn FamilyPlans,
    guards: &OwnerGuards,
) -> Result<StepResult, HostViolation> {
    PreImage::bind(a, img)?; // AB first, before any table read.
    if img.fin.is_some() {
        return Err(fin_unsupported(FinUnsupportedOp::Step));
    }
    if img.outcome != OutcomeC::Running {
        return Ok(StepResult::Terminal);
    } // P0
    let pre_snap = snap(&PreImage::bind(a, img)?)?; // pure pre-image event snapshot; no write precedes it
    // P1 publish (helper and result absent only).
    if img.helper.is_none() && img.result.is_none() {
        match img.control {
            ControlC::Error { code } => {
                img.outcome = OutcomeC::Rejected { code };
                return Ok(publish_event(
                    a,
                    &pre_snap,
                    img,
                    RuleIdC::KAdminPublishError,
                    StepDisposition::Published,
                    None,
                    None,
                ));
            }
            ControlC::Return { value } if img.frames.is_empty() => {
                img.outcome = OutcomeC::Halted { value };
                return Ok(publish_event(
                    a,
                    &pre_snap,
                    img,
                    RuleIdC::KAdminPublishValue,
                    StepDisposition::Published,
                    None,
                    None,
                ));
            }
            _ => {}
        }
    }
    if img.remaining_work == 0 {
        img.outcome = OutcomeC::Exhausted {
            reason: ExhaustReason::Fuel,
        }; // P2
        return Ok(publish_event(
            a,
            &pre_snap,
            img,
            RuleIdC::KAdminPublishExhausted,
            StepDisposition::ExhaustedFuelUncharged,
            Some(ExhaustReason::Fuel),
            pre_snap.helper.as_ref().map(helper_kind_of),
        ));
    }
    // PS: select + plan + validate + physical, all pure over the pre-image.
    let (sel, validated) = {
        let pre = PreImage::bind(a, img)?;
        let sel = owner_select(&pre, guards)?;
        let (plan, read_provenance, read_env_provenance) =
            call_family(families, &sel, &pre, guards)?;
        let validated =
            owner_validate_plan(&pre, &sel, plan, &read_provenance, &read_env_provenance)?;
        owner_physical_check(&pre, &validated)?;
        (sel, validated)
    };
    let cap = owner_cap_refusal(&validated);
    // P3 helper-work refusal, uncharged.
    if sel.helper_eligible && img.helper_work == a.body.bounds.max_helper_work {
        img.outcome = OutcomeC::Exhausted {
            reason: ExhaustReason::HelperWork,
        };
        return Ok(StepResult::Event {
            event: build_event(
                a,
                &pre_snap,
                img,
                pre_snap.consumed,
                sel.rule,
                sel.event_kind,
                sel.site,
                sel.helper_kind,
                StepDisposition::RefusedHelperWorkUncharged,
                0,
                0,
                0,
                AllocDeltasC {
                    data_nodes: 0,
                    data_fields: 0,
                    environment_cells: 0,
                },
                0,
                Some(ExhaustReason::HelperWork),
            ),
        });
    }
    // P4 charge exactly once.
    let remaining_work = img
        .remaining_work
        .checked_sub(1)
        .ok_or_else(|| arith("P4 remainingWork - 1"))?;
    let consumed_work = img
        .consumed_work
        .checked_add(1)
        .ok_or_else(|| arith("P4 consumedWork + 1"))?;
    let helper_work = if sel.helper_eligible {
        Some(
            img.helper_work
                .checked_add(1)
                .ok_or_else(|| arith("P4 helperWork + 1"))?,
        )
    } else {
        None
    };
    img.remaining_work = remaining_work;
    img.consumed_work = consumed_work;
    if let Some(helper_work) = helper_work {
        img.helper_work = helper_work;
    }
